t(),L=j(()=>["ar","ku"].includes(C.value)),x=j(()=>C.value==="zh"),ee=[{id:"q1",num:"01",q_ar:"ما هي الوثائق المطلوبة لغرض التقديم على البطاقة التموينية الإلكترونية؟",a_ar:"يتم إعتماد البطاقة الوطنية الموحدة ومعلومات البطاقة التموينية الورقية (المعمول بها سابقاً) لغرض التقديم على البطاقة التموينية الإلكترونية والتحقق من صلة القرابة.",q_zh:"申领与核发国家电子配给卡需要准备哪些官方证明文件？",a_zh:"依据贸易部规程，必须核验申请人持有的【统一国家身份证】（البطاقة الوطنية الموحدة）以及原纸质配给卡（البطاقة التموينية الورقية）底册信息，用以确认家庭关系链条与额度归属。",q_en:"What official documents are required to apply for the Electronic Ration Card?",a_en:"The Unified National Card and details from the previous paper ration card are required to establish family relationships and entitlement quotas."},{id:"q2",num:"02",q_ar:"ما هو الإجراء المناسب لتصحيح المعلومات في حال تم رفعها بصورة خاطئة؟",a_ar:"يمكن تعديل المعلومات من خلال التطبيق عن طريق واجهة المستخدم وتقديم طلب استدراك فوري لمراجعته في مركز التدقيق المعني.",q_zh:"填报录入或上传信息出现误差时，法定的纠偏更正程序是什么？",a_zh:"公民可在应用程序内发起数据更正申请，或由辖区监管官在后台【电子配给卡管理】工作台执行实名纠偏审核与变更备案。",q_en:"What is the procedure for correcting erroneous information submitted?",a_en:"Information can be corrected through the user application or submitted for administrative review at the designated audit center."},{id:"q3",num:"03",q_ar:"ما هو الإجراء المناسب عند وجود نقص في أحد أفراد الأسرة؟",a_ar:"يجب إكمال عملية التقديم للأفراد الموجودين فقط حسب معلومات البطاقة التموينية، وإضافة الفرد الناقص في وقت لاحق عن طريق التطبيق بإرفاق شهادة الولادة أو القيد.",q_zh:"若发现在册家庭成员清单存在遗漏或人口未登记，该如何妥善处置？",a_zh:"应先按现有完整成员提交初审并确保基本配额不受阻碍，随后通过【家庭成员增补申报】通道上传新生儿出生证明或户籍证明补录。",q_en:"How to handle omissions when a family member is missing from the registry?",a_en:"Complete the initial application for existing members first, then submit a supplemental member registration with supporting documents later."},{id:"q4",num:"04",q_ar:"في حال نسيان أو ضياع رقم البطاقة التموينية أو كلمة المرور، ما هو الإجراء؟",a_ar:'يمكن طلب معلومات جديدة لتسجيل الدخول من خلال الضغط على "نسيت كلمة المرور؟" وسيتم إرسال رمز تحقق عبر الرسائل النصية القصيرة SMS إلى الهاتف المسجل.',q_zh:"配给卡号遗失或遗忘登录凭证时，如何通过安全通道重置？",a_zh:"系统提供基于短信安全校验码（OTP）及国家身份证号的双重找回机制，亦可由辖区管理官依据档案底册进行现场复核恢复。",q_en:"How to recover a forgotten ration card number or password?",a_en:'Use the "Forgot Password" feature to receive an SMS verification code to the registered mobile number or visit the audit center.'},{id:"q5",num:"05",q_ar:"في حال توقف أو ضياع رقم الهاتف المسجل، كيف يمكن تغييره؟",a_ar:"يتم مراجعة أقرب مركز تمويني مصطحباً الوثائق الثبوتية الرسمية لتحديث رقم الهاتف وضمان عدم استغلال الحساب من قبل أطراف غير مصرح لها.",q_zh:"原预留手机号停机、注销或遗失，如何办理换绑？",a_zh:"为防范配给冒领风险，持卡人需持统一身份证前往辖区配给中心或由管理员通过政务系统核实身份后，执行安全换绑并记入审计日志。",q_en:"How can a citizen update a disconnected or lost phone number?",a_en:"Visit the nearest ration audit center with official ID to securely update the registered phone number."},{id:"q6",num:"06",q_ar:"هل التقديم على البطاقة التموينية الإلكترونية مجانياً؟",a_ar:"نعم، التقديم وإصدار البطاقة التموينية الإلكترونية مجاني بالكامل ولا تترتب عليه أي رسوم مالية على المواطن.",q_zh:"电子配给卡的申领、建档与发卡是否收取行政规费？",a_zh:"全国电子配给卡全流程【100% 免费】，严禁任何代销代理网点或机构以工本费、服务费等名义向公民收取任何费用，违者依法取消代理权。",q_en:"Is applying for the Electronic Ration Card free of charge?",a_en:"Yes, the application and issuance of the Electronic Ration Card is completely free without any fees charged to citizens."},{id:"q7",num:"07",q_ar:"ما هو تقنية NFC وكيف يتم استخدامها في التوزيع والتحقق؟",a_ar:"تتيح تقنية الاتصال قريب المدى (NFC) قراءة بيانات البطاقة الذكية بمجرد تقريب الهاتف منها لضمان تسليم الحصص بدقة ومنع التلاعب.",q_zh:"NFC 近场通信技术在物资核销与现场配送中扮演何种角色？",a_zh:"代理网点手机或 POS 机通过 NFC 触碰公民物理芯片卡，可实现毫秒级防篡改握手核验，确保物资精准交付到本人手中，杜绝虚假代领。",q_en:"What is NFC technology and how is it used during distribution?",a_en:"NFC allows contactless verification by tapping the smart card against the agent terminal to confirm physical delivery and prevent fraud."},{id:"q8",num:"08",q_ar:"هل سيتم إهمال وإلغاء البطاقة التموينية الورقية نهائياً؟",a_ar:"سيتم الاستغناء التدريجي عن البطاقة الورقية بعد اكتمال مرحلة التحول الرقمي الشامل في جميع المحافظات لضمان عدم انقطاع الإمدادات الغذائية.",q_zh:"传统的纸质配给卡是否会立即全面废止？",a_zh:"采取平稳有序的过渡方针：待各省份电子卡完成全量发卡与活体验证覆盖后，分批次废止纸质凭证，确保过渡期内物资保供不间断。",q_en:"Will paper ration cards be decommissioned completely?",a_en:"Paper cards are phased out progressively once full digital coverage is validated in each province to ensure continuity of supplies."},{id:"q9",num:"09",q_ar:"كيفية حذف أحد أفراد الأسرة وما هي الحالات القانونية الموجبة لذلك؟",a_ar:"يتم تقديم طلب الحذف في حالات الوفاة أو السفر الدائم خارج القطر أو الانتقال لتكوين أسرة مستقلة، مع إرفاق الوثائق الرسمية المؤيدة.",q_zh:"家庭成员注销扣减核减的法定准则与适用情形有哪些？",a_zh:"适用于家庭成员亡故、长期定居境外、或结婚分立独立配给卡户头。须提交死亡证明或分立决议，经审核后冻结对应月度口粮配额。",q_en:"Under what circumstances should a family member be deregistered?",a_en:"Deregistration applies in cases of death, permanent emigration, or household splitting, supported by official certificates."},{id:"q10",num:"10",q_ar:"هل من الضروري حضور جميع أفراد الأسرة إلى مركز التدقيق؟",a_ar:"يكفي حضور رب الأسرة أو من ينوب عنه رسمياً مصطحباً الوثائق الأصلية لجميع الأفراد لإتمام إجراءات التدقيق والتوثيق.",q_zh:"办理线下复核时是否要求家庭全体成员全员到场？",a_zh:"原则上仅需法定户主（رب الأسرة）或具法定委托书的代理人携带全员原始身份证件到场复核即可，以减轻公众出行与窗口拥堵负担。",q_en:"Must all family members appear in person at the audit center?",a_en:"The head of household or authorized legal representative carrying original documents for all members is sufficient."}],pe=h(""),oe=h({q1:!0,q2:!0,q6:!0}),B=h(!1),ce=j(()=>{const N=pe.value.trim().toLowerCase();return N?ee.filter(O=>O.q_ar.toLowerCase().includes(N)||O.a_ar.toLowerCase().includes(N)||O.q_zh.toLowerCase().includes(N)||O.a_zh.toLowerCase().includes(N)||O.q_en.toLowerCase().includes(N)||O.a_en.toLowerCase().includes(N)):ee});function he(N){oe.value[N]=!oe.value[N]}function Ce(){B.value=!B.value,ee.forEach(N=>{oe.value[N.id]=B.value})}function le(N){return L.value?N.q_ar:x.value?N.q_zh:N.q_en}function fe(N){return L.value?N.a_ar:x.value?N.a_zh:N.a_en}r